{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "GSK1322322, a molecule with a basic piperazine and multiple H-bond acceptors, had 57% absolute oral bioavailability in fasted healthy volunteers, directly supporting F ≥ 20% for a similarly polar/ionizable query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Linezolid oral tablets have ~100% absolute bioavailability, demonstrating that oral absorption can be complete even with polar functional groups and multiple H-bond acceptors.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Apalutamide had an absolute oral bioavailability of approximately 1.0 in a phase 1 IV-microtracer study, providing strong evidence that a moderately lipophilic, high-TPSA oral drug can achieve essentially complete absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Paliperidone extended-release, an ionizable drug with a basic amine, had 28% absolute oral bioavailability, still above the 20% threshold despite a deliberately slow-release formulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Tacrolimus oral bioavailability is approximately 20–25%, the lowest among the transferred analogues, yet it still meets the F ≥ 20% criterion, indicating the query is unlikely to fall below threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Ketanserin had 46.8% absolute oral bioavailability in healthy subjects, providing another direct experimental example of moderate-to-high F in a molecule with substantial polar surface area and H-bonding capacity.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show absolute oral bioavailability at or above 20%, with most values between 28% and 100%; the physicochemical prior suggesting low absorption is overridden by consistent experimental evidence for high F.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself; the prediction relies on high-transfer analogues.",
    "No explicit efflux/transporter or permeability data are available for the query, but transferred analogues with similar ionizable/piperazine features still achieved F ≥ 20%.",
    "Some analogue F values are formulation-dependent (e.g., paliperidone ER vs IR), but all relevant values remain at or above the 20% threshold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

